/* remix.js — part of the universal player. Generated by the one-off split;
 * every top-level name lives on the shared context P (see context.js). */
import { P } from "./context.js";

export function install(P) {


  /* ---------- remix create / save / load ---------- */

  function showRemixMessage(message) {
    document.querySelectorAll("[data-remix-message]").forEach((el) => { el.textContent = message || ""; });
    if (P.remixMessageTimer) window.clearTimeout(P.remixMessageTimer);
    P.remixMessageTimer = window.setTimeout(() => {
      document.querySelectorAll("[data-remix-message]").forEach((el) => { el.textContent = ""; });
      P.remixMessageTimer = 0;
    }, 5000);
  }

  function rememberRemixUrl(url) {
    if (P.loadedRemixUrl) window.setTimeout(() => URL.revokeObjectURL(P.loadedRemixUrl), 8000);
    P.loadedRemixUrl = url || "";
  }

  function remixBaseName() {
    const source = P.sourceTrackPath(P.state.current) || "remix";
    return String(P.state.current?.title || source)
      .replace(/\.[^.]+$/, "")
      .replace(/[\\/:*?"<>|]+/g, "_") || "track";
  }

  function downloadBlob(blob, filename) {
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement("a");
    anchor.href = url;
    anchor.download = filename;
    document.body.appendChild(anchor);
    anchor.click();
    anchor.remove();
    window.setTimeout(() => URL.revokeObjectURL(url), 10000);
  }

  async function bakeRemixNow() {
    if (!P.state.current) { P.showRemixMessage(P.pt("remixNoTrack")); return; }
    if (!P.anyFxEnabled()) { P.showRemixMessage(P.pt("remixNoFx")); return; }
    if (P.fxRenderTimer) window.clearTimeout(P.fxRenderTimer);
    P.fxRenderTimer = 0;
    P.fxRenderDeadline = 0;
    P.stopFxCountdown();
    P.fxRenderToken++;
    const token = P.fxRenderToken;
    const track = P.state.current;
    const wasPlaying = !P.audio.paused;
    const position = P.audio.currentTime || 0;
    P.setFxRendering(true);
    const baked = await P.ensureRenderedTrack(track);
    if (token !== P.fxRenderToken || P.state.current !== track) return;
    P.setFxRendering(false, !baked);
    if (!baked) { P.showRemixMessage(P.pt("remixError")); return; }
    P.loadCurrent({ autoplay: wasPlaying, startTime: position, fadeIn: false });
    P.showRemixMessage(P.pt("remixCreated"));
  }

  function remixExtension(blob, format) {
    const mime = String(blob.type || "");
    if (format === "ogg" || mime.includes("ogg")) return "ogg";
    if (format === "mp3" || mime.includes("mpeg")) return "mp3";
    if (mime.includes("webm")) return "webm";
    return format === "opus" ? "opus" : format;
  }

  async function saveRemix(format) {
    if (!P.state.current) { P.showRemixMessage(P.pt("remixNoTrack")); return; }
    const fmt = P.REMIX_FORMATS.includes(format) ? format
      : (P.REMIX_FORMATS.includes(P.state.remixFormat) ? P.state.remixFormat : "wav");
    try {
      if (fmt !== "wav" && fmt !== "flac" && !(await P.recorderMime(fmt))) {
        P.showRemixMessage(P.pt("remixUnsupported", { format: fmt.toUpperCase() }));
        return;
      }
      const track = P.state.current;
      let url = P.sourceUrl(track);
      if (P.anyFxEnabled()) {
        const baked = await P.ensureRenderedTrack(track);
        if (!baked) throw new Error("render failed");
        url = P.resolveTrackPath(track);
      }
      P.showRemixMessage(P.pt("remixEncoding", { format: fmt.toUpperCase() }));
      const buffer = await P.decodeUrlToBuffer(url);
      if (!buffer) throw new Error("decode failed");
      const blob = fmt === "wav" ? await P.encodeWav(buffer)
        : fmt === "flac" ? await P.encodeFlac(buffer)
          : await P.encodeWithMediaRecorder(buffer, fmt);
      P.downloadBlob(blob, `${P.remixBaseName()}-remix.${P.remixExtension(blob, fmt)}`);
      P.showRemixMessage(P.pt("remixSaved"));
    } catch {
      P.showRemixMessage(P.pt("remixError"));
    }
  }

  function loadRemixFile(file) {
    if (P.programLocked || !file) return;
    try {
      const url = URL.createObjectURL(file);
      P.rememberRemixUrl(url);
      const title = `${P.state.current?.title || file.name} — ${P.pt("loadRemix")}`;
      P.playTrack({
        id: `remix-${Date.now()}`,
        title: P.pt("loadRemix"),
        cover: P.state.current?.cover || null,
        tracks: [{ title, path: url, formats: {} }],
      }, 0, { autoplay: true });
      P.showRemixMessage(P.pt("remixLoaded"));
    } catch {
      P.showRemixMessage(P.pt("remixError"));
    }
  }
  Object.assign(P, { showRemixMessage, rememberRemixUrl, remixBaseName, downloadBlob, bakeRemixNow, remixExtension, saveRemix, loadRemixFile });
}
